import {cumulativeEscape as esc,cumulativeButton as button,cumulativeRange as range,cumulativeFields,mountCumulativeSurface} from './cumulative-view.js';
const reading=(version,opened)=>`<div class="lt-stack"><p id="lt-cumulative-body-${esc(version.id)}" class="ui-reading ${opened?'':'lt-copy'}">${esc(version.body).replace(/\n/g,'<br>')}</p>${version.body.length>180?`<div class="ui-action-group">${button(opened?'收起正文':'展开正文',`body:${version.id}`,false,'tertiary',`aria-expanded="${!!opened}" aria-controls="lt-cumulative-body-${esc(version.id)}"`)}</div>`:''}<p class="lt-meta">故事时间 ${esc(version.startTime)}—${esc(version.endTime)}</p></div>`;export function cumulativeRootMarkup(state,{showToast=true}={}){const domain=state.cumulative,version=domain?.versions.at(-1),editing=!!state.editDraft,busy=state.busy||state.unconfirmed||state.reloadInvalidated;
  return `${showToast?'<p class="lt-saved lt-status" data-cu-toast role="status" hidden></p>':''}<nav class="lt-work-actions lt-management-actions ui-action-grid" aria-label="古法总结操作">${button('手动总结','manual',busy)}${button('自动总结','auto',busy)}${button('总结设置','settings',busy)}</nav><p class="lt-error" role="alert" ${state.error?'':'hidden'}>${esc(state.error)}</p><section class="lt-stack ui-section"><h2>当前记忆</h2>${version?`<article class="lt-row ui-card ui-graphic-card"><div class="lt-stack">${editing?cumulativeFields(state.editDraft,'edit'):reading(version,state.opened[`body:${version.id}`])}<p class="lt-meta">来源楼层 ${esc(range(version))}</p>${editing?'':button('编辑记忆','edit',busy,'primary')}</div></article>`:'<p class="lt-empty">暂无古法记忆</p>'}</section><section class="lt-stack ui-section"><h2>历史版本</h2>${(domain?.versions.slice(0,-1)??[]).toReversed().map(item=>`<details class="lt-summary-history ui-disclosure" data-cu-open="history:${esc(item.id)}"><summary>${esc(range(item))} 楼</summary><article class="lt-row ui-card ui-graphic-card ui-disclosure-body">${reading(item,state.opened[`body:${item.id}`])}${button('恢复此版',`restore:${item.id}`,busy||editing,'secondary')}</article></details>`).join('')||'<p class="lt-meta">暂无历史版本</p>'}</section>${button('重新读取','read',state.busy,'tertiary',state.unconfirmed||state.reloadInvalidated?'':'hidden')}`;
}
export function cumulativeRootFooter(state){if(state.restore)return `<div class="lt-delete-confirmation" role="group" aria-label="恢复古法版本"><p>恢复来源 ${esc(range(state.restore.version))} 楼的版本，移除后续 ${state.restore.removed} 个版本；总结进度回到第${Math.max(...state.restore.version.coverageRanges.map(item=>item.end))}楼。</p><div class="lt-editor-actions">${button('取消','cancel-restore',state.busy)}${button('确认恢复','confirm-restore',state.busy||state.unconfirmed||state.reloadInvalidated,'secondary')}</div></div>`;return state.editDraft?`<div class="lt-editor-actions">${button('保存','save-edit',state.busy||state.unconfirmed||state.reloadInvalidated,'primary')}</div>`:'';}
// Mount only the workface. Host supplies its existing header/navigation and fixed footer.
export function mountCumulativeRootView({container,footerContainer,toastContainer=null,controller,onManual=()=>{},onAuto=()=>{},onSettings=()=>{}}={}){let view;view=mountCumulativeSurface({container,footerContainer,toastContainer,controller,markup:state=>cumulativeRootMarkup(state,{showToast:!toastContainer}),footer:cumulativeRootFooter,preserveMain:(state,previous)=>!!(state.restore||previous.restore)&&JSON.stringify(state.cumulative)===JSON.stringify(previous.cumulative)&&state.unconfirmed===previous.unconfirmed,scope:state=>JSON.stringify([state.target,'root']),input(node){const [kind,key]=(node.dataset.cuField??'').split(':');if(kind==='edit')controller.changeEdit(draft=>draft[key]=node.value);},async click(action){if(action==='manual')onManual();if(action==='auto')onAuto();if(action==='settings')onSettings();if(action==='edit')controller.beginEdit();if(action==='save-edit')await controller.saveEdit();if(action.startsWith('restore:'))controller.requestRestore(action.slice(8));if(action==='cancel-restore'){const id=controller.inspect().restore?.id;controller.cancelRestore();[...container.querySelectorAll('[data-cu-action]')].find(node=>node.dataset.cuAction===`restore:${id}`)?.focus({preventScroll:true});}if(action==='confirm-restore')await controller.confirmRestore();if(action==='read')await controller.read();if(action.startsWith('body:')){const state=controller.inspect();controller.setOpen(action,!state.opened[action]);view.render();}}});const escape=event=>{if(event.key!=='Escape'||!controller.inspect().restore)return;event.preventDefault();event.stopPropagation();const id=controller.inspect().restore.id;controller.cancelRestore();[...container.querySelectorAll('[data-cu-action]')].find(node=>node.dataset.cuAction===`restore:${id}`)?.focus({preventScroll:true});};container.addEventListener('keydown',escape);footerContainer?.addEventListener('keydown',escape);return {dispose(){container.removeEventListener('keydown',escape);footerContainer?.removeEventListener('keydown',escape);view.dispose();}};}
